// @vitest-environment jsdom
import fs from 'node:fs';import path from 'node:path';import {beforeEach,afterEach,describe,it,expect}from'vitest';import {createRoot,type Root}from'react-dom/client';import{flushSync}from'react-dom';import React,{useState}from'react';
import{loadDraft,saveDraft,loadDraftAttachments,saveDraftAttachments,loadDraftSubmission,saveDraftSubmission}from'@/lib/composer-draft';
const source=fs.readFileSync(path.resolve(process.cwd(),fs.existsSync(path.resolve(process.cwd(),'src/pages/IssueDetail.tsx'))?'src/pages/IssueDetail.tsx':'ui/src/pages/IssueDetail.tsx'),'utf8');
const producerLine=source.split('\n').find(line=>line.includes('draftKey={')&&line.includes('paperclip:issue-comment-draft:'))!.trim();
const producer=producerLine.slice('draftKey={'.length,-1);
const threadSection=source.slice(source.indexOf('<ThreadComponent'));
const keyLine=threadSection.split('\n').find(line=>line.trim().startsWith('key={'))!.trim();
const threadKey=keyLine.slice('key={'.length,-1);
function evaluate(expression:string,context:Record<string,unknown>){return Function(...Object.keys(context),`return (${expression});`)(...Object.values(context));}
function key(user:string|null,ready=true,task='same-task',company='same-company',agent:string|null=null):string|undefined{return evaluate(producer!,{currentUserId:user,sessionResolved:ready,issue:{id:task,companyId:company},conversationAgent:agent?{id:agent}:null});}
let root:Root|undefined;let host:HTMLDivElement|undefined;beforeEach(()=>{localStorage.clear();sessionStorage.clear();});afterEach(()=>{if(root)flushSync(()=>root!.unmount());root=undefined;host?.remove();host=undefined;});
describe('IssueDetail production draft owner boundary',()=>{
 it('isolates text, attachments and pending submissions for A/B viewing the same task',()=>{const a=key('A')!,b=key('B')!;saveDraft(a,'A private unsent text');const receipt={attachmentId:'9af8228f-0be7-45ae-a104-6fbe0af6f1d3',name:'private.txt',size:1,inline:false,contentPath:'/api/attachments/9af8228f-0be7-45ae-a104-6fbe0af6f1d3/content'};saveDraftAttachments(a,[receipt]);saveDraftSubmission(a,{attemptId:'9af8228f-0be7-45ae-a104-6fbe0af6f1d3',reviewed:false});expect(loadDraft(b)).toBe('');expect(loadDraftAttachments(b)).toEqual([]);expect(loadDraftSubmission(b)).toBeNull();saveDraft(b,'B own draft');expect(loadDraft(a)).toBe('A private unsent text');});
 it('keeps the same account draft across reload and task navigation without adopting legacy unowned storage',()=>{const owned=key('A')!;const legacy='paperclip:issue-comment-draft:same-task';localStorage.setItem(legacy,'unknown owner legacy');expect(loadDraft(owned)).toBe('');saveDraft(owned,'A recoverable text');expect(loadDraft(key('A')!)).toBe('A recoverable text');expect(loadDraft(key('A',true,'other-task')!)).toBe('');expect(loadDraft(key('A')!)).toBe('A recoverable text');expect(localStorage.getItem(legacy)).toBe('unknown owner legacy');});
 it('uses no persistent shared key while auth is loading or has no actor',()=>{expect(key(null,false)).toBeUndefined();expect(key('A',false)).toBeUndefined();expect(key(null,true)).toBeUndefined();expect(key(null,false,'same-task','same-company','agent')).toBeUndefined();});
 it('preserves local_trusted stable local-board session ownership',()=>{const owned=key('local-board')!;saveDraft(owned,'local operator draft');expect(loadDraft(key('local-board')!)).toBe('local operator draft');expect(key('A')).not.toBe(owned);expect(key('local-board',true,'same-task','other-company')).not.toBe(owned);});
 it('remounts the production thread boundary before rendering a different account or pending auth',()=>{saveDraft(key('A')!,'A private text');host=document.createElement('div');document.body.appendChild(host);root=createRoot(host);function Buffer({storageKey}:{storageKey:string|undefined}){const[body]=useState(()=>storageKey?loadDraft(storageKey):'');return <span>{body}</span>;}function render(user:string|null,ready=true){const draftKey=key(user,ready);const rendererKey=evaluate(threadKey!,{draftKey,issueId:'same-task',conversationMode:false});flushSync(()=>root!.render(<Buffer key={rendererKey} storageKey={draftKey}/>));}render('A');expect(host.textContent).toBe('A private text');render(null,false);expect(host.textContent).toBe('');render('B');expect(host.textContent).toBe('');render('A');expect(host.textContent).toBe('A private text');});
});
